(() => {
  const style=document.createElement('style');style.textContent=`.path{max-width:980px;margin:0 auto}.path-hero{padding:30px;border-radius:24px;background:var(--navy);color:#fff;box-shadow:var(--shadow)}.path-hero h2{margin:8px 0;font-size:clamp(1.6rem,3vw,2.35rem)}.path-hero p{margin:0;color:#dbe8f5;line-height:1.65;max-width:720px}.path-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:13px;margin:18px 0}.path-card{padding:19px;border-radius:17px;background:#fff;border:1px solid var(--line);box-shadow:0 8px 22px rgba(24,48,75,.06)}.path-card b{display:block;color:var(--navy);font-size:1.05rem}.path-card small{display:block;color:var(--muted);line-height:1.5;margin:7px 0 14px}.path-card.done{background:var(--mint);border-color:#a9d9c4}.path-work{padding:28px;border-radius:24px;background:#fff;box-shadow:var(--shadow)}.path-work h2{margin:8px 0;color:var(--navy)}.path-work p{line-height:1.7}.learn-item{padding:16px 0;border-top:1px solid var(--line)}.learn-item:first-of-type{border-top:0}.learn-item b{color:var(--navy)}.learn-item input,.learn-item textarea{width:100%;margin-top:10px;padding:11px 12px;border:1px solid var(--line);border-radius:10px;font:inherit}.learn-item textarea{min-height:74px;resize:vertical}.learn-answer{display:none;margin-top:10px;padding:11px 12px;border-radius:10px;background:#f6faff;color:#314963;line-height:1.6}.learn-answer.show{display:block}.passage{padding:17px;border:1px solid #d7e5f4;border-radius:14px;background:#f6faff;line-height:1.8;font-family:Georgia,serif}.path-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.feedback{display:none;margin-top:12px;padding:12px;border-radius:10px;line-height:1.6}.feedback.show{display:block}.feedback.good{background:var(--mint);color:#245846}.feedback.bad{background:#fff4f1;color:#8b3c35}@media(max-width:720px){.path-grid{grid-template-columns:1fr 1fr}.path-work{padding:21px}}`;document.head.appendChild(style);
  const key='ci-jing-20-minute-v1',date=()=>new Date().toISOString().slice(0,10);const get=()=>{try{const x=JSON.parse(localStorage.getItem(key));return x?.date===date()?x:{date:date(),done:[]}}catch{return{date:date(),done:[]}}};const save=x=>localStorage.setItem(key,JSON.stringify(x));
  const units=[
    {id:'vocab',title:'词汇与搭配',time:'6 分钟',note:'4 个词组 · 先学后测'},
    {id:'grammar',title:'语法语境',time:'4 分钟',note:'1 个结构 · 3 个变式'},
    {id:'main',title:'主训练',time:'6 分钟',note:'阅读或完形轮换'},
    {id:'test',title:'专项测试',time:'按需 4 分钟',note:'完成专项后再测'}
  ];
  const hub=document.getElementById('studyHub'),shell=document.getElementById('studyShell');
  function hubView(){const state=get();hub.classList.remove('hidden');shell.classList.add('hidden');const learned=units.filter(u=>['vocab','grammar','main'].includes(u.id)&&state.done.includes(u.id));hub.innerHTML=`<div class="path"><div class="path-hero"><div class="eyebrow">今日推荐 · 最多 20 分钟</div><h2>先做最重要的，也可以只练一项。</h2><p>词汇搭配和语法保持每日不断线；主训练按阅读、完形、翻译写作轮换。专项测试只对已完成的模块开放。</p><div class="path-actions"><button class="primary" id="startSuggested">开始今日 20 分钟</button></div></div><div class="path-grid">${units.map((u,i)=>`<article class="path-card ${state.done.includes(u.id)?'done':''}"><b>${i+1}. ${u.title}</b><small>${u.time}<br>${u.note}</small><button class="secondary" data-unit="${u.id}" ${u.id==='test'&&!learned.length?'disabled':''}>${u.id==='test'?(learned.length?'选择已学专项':'先完成一个专项'):state.done.includes(u.id)?'再次练习':'开始练习'}</button></article>`).join('')}</div><p class="smallnote">当前内容均为编辑练习，不标为上海高考正式真题。专项测试错题将在下一次同类学习中优先出现。</p></div>`;hub.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>b.dataset.unit==='test'?testPicker():unitView(b.dataset.unit));document.getElementById('startSuggested').onclick=()=>unitView('vocab')}
  function testPicker(){const state=get(),choices=units.filter(u=>['vocab','grammar','main'].includes(u.id)&&state.done.includes(u.id));hub.classList.add('hidden');shell.classList.remove('hidden');shell.innerHTML=`<div class="path"><button class="secondary study-back" id="backPath">返回学习中心</button><div class="path-work"><span class="badge">专项测试 · 仅测试已学习内容</span><h2>选择要验证的专项。</h2><p>测试只针对你已完成的学习模块，不混入尚未学习的词汇、语法或阅读内容。</p><div class="path-actions">${choices.map(u=>`<button class="primary" data-target="${u.id}">测试：${u.title}</button>`).join('')}</div></div></div>`;shell.querySelector('#backPath').onclick=hubView;shell.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>unitView('test',b.dataset.target))}

  const words=[['provide','提供','provide sb with sth','The library provides students with a quiet place to read.'],['reflect','反映，体现','reflect students’ needs','The survey reflects what students need most.'],['acquire','逐步获得','acquire knowledge / skills','Students acquire useful skills through regular practice.'],['affect','影响（动词）','affect concentration','A lack of sleep may affect concentration.']];
  const grammar=[['If I ___ you, I would ask the teacher for help. (be)','were','与现在事实相反的假设，书面语常用 were。'],['Not only did she finish the report, ___ she also explained the data.','but','not only 与 but also 对应；前半句倒装。'],['The book ___ by the student won a prize. (write)','written','book 是“被写”，用过去分词作后置定语。']];
  function learningCards(){return `<p>这里是<strong>学习</strong>，不要求你把已经显示的答案再输入一次。先看语境和用法；之后到“今日小测”做闭卷提取。</p>${words.map((w,i)=>`<article class="learn-item"><b>${i+1}. ${w[0]}</b><p class="en">${w[3]}</p><button class="secondary reveal-learn" data-index="${i}">显示词义与搭配</button><div class="learn-answer" id="word-${i}"><b>${w[1]}</b> · ${w[2]}<br>试着口头说出：这个词在此句中表示什么？搭配的结构是什么？</div></article>`).join('')}`}
  function grammarCards(){return `<p>先判断句子关系，再显示答案和原因。三题构成同一轮短练，不是孤立背规则。</p>${grammar.map((g,i)=>`<article class="learn-item"><b>${i+1}. ${g[0]}</b><button class="secondary reveal-grammar" data-index="${i}">显示答案与原因</button><div class="learn-answer" id="grammar-${i}"><b>答案：${g[1]}</b><br>${g[2]}</div></article>`).join('')}`}
  function mainCards(){const read=new Date().getDate()%2;return read?`<p>完整阅读与证据推断 · 编辑练习。先读完材料，再回答问题；不能只凭一句话推断。</p><div class="passage">A school library began opening for one extra hour after classes. In the first month, more students visited the library, especially those preparing group projects. Some students said the quieter space helped them concentrate. However, the school did not compare their exam results with those of students who did not use the library. The librarian therefore described the change as “a useful service improvement”, rather than proof that the extra hour raised academic achievement.</div><article class="learn-item"><b>学习任务</b><p>找出：① 能直接确定的事实；② 限制“提高成绩”结论的证据；③ 你自己的推理链。</p><button class="secondary" id="showEvidence">查看证据示范</button><div class="learn-answer" id="evidenceAnswer"><b>事实：</b>更多学生到图书馆。<br><b>限制证据：</b>学校没有比较使用与未使用图书馆学生的考试结果。<br><b>结论：</b>可认为服务改善，不能断言成绩提高。</div></article>`:`<p>完整完形篇章 · 编辑练习。先读主题和逻辑，再逐空判断。</p><div class="passage">When Mia first joined the reading club, she tried to finish every book as quickly as possible. After several weeks, however, she found that speed did not always lead to understanding. Her teacher suggested that she ___ short notes while reading and return to confusing parts later. Mia then began to notice how examples ___ the writer’s main idea. She also learned to ___ attention to linking words. The habit took only ten minutes a day, but it made her reading more ___ and less stressful.</div><article class="learn-item"><b>学习任务</b><p>先说出每空分别考搭配、词义还是篇章逻辑，再查看分析。</p><button class="secondary" id="showCloze">查看答案与分析</button><div class="learn-answer" id="clozeAnswer"><b>take / illustrate / pay / effective</b><br>take notes 与 pay attention to 是搭配；illustrate 表示例子说明主旨；effective 与 less stressful 共同描述阅读效果。</div></article>`}
  function testCards(target){const tests={vocab:`<p>闭卷测试 · 只测试已学习的词汇与搭配。</p><article class="learn-item"><b>1. 填入：The club ___ members ___ a guide.</b><input data-key="provides with" placeholder="写出两个空的答案"></article><article class="learn-item"><b>2. 填入：A lack of sleep may ___ concentration.</b><input data-key="affect" placeholder="答案"></article>`,grammar:`<p>闭卷测试 · 只测试已学习的语法结构。</p><article class="learn-item"><b>1. 填入：If I ___ more time, I would read the whole report. (have)</b><input data-key="had" placeholder="答案"></article><article class="learn-item"><b>2. 填入：The book ___ by the student won a prize. (write)</b><input data-key="written" placeholder="答案"></article>`,main:`<p>闭卷测试 · 只测试刚完成的篇章训练。</p><article class="learn-item"><b>在材料中定位限制结论的证据，并补全：The school ___ exam results of users and non-users.</b><input data-key="did not compare" placeholder="填入英文短语"><div class="journey-note">提示：找出学校没有做的那件事；这说明不能直接把延长开放时间等同于成绩提高。</div></article>`};return tests[target]+'<div class="feedback" id="testFeedback"></div>'}

  function unitView(id,target){const u=units.find(x=>x.id===id);hub.classList.add('hidden');shell.classList.remove('hidden');const content=id==='vocab'?learningCards():id==='grammar'?grammarCards():id==='main'?mainCards():testCards(target);shell.innerHTML=`<div class="path"><button class="secondary study-back" id="backPath">返回学习中心</button><div class="path-work"><span class="badge">${u.time} · ${u.id==='test'?'闭卷验证':'可单独完成'}</span><h2>${id==='test'?'专项测试：'+units.find(x=>x.id===target).title:u.title}</h2>${content}<div class="path-actions"><button class="primary" id="finishUnit">${id==='test'?'提交并批改':'完成本项'}</button></div></div></div>`;shell.querySelector('#backPath').onclick=hubView;shell.querySelectorAll('.reveal-learn').forEach(b=>b.onclick=()=>document.getElementById('word-'+b.dataset.index).classList.add('show'));shell.querySelectorAll('.reveal-grammar').forEach(b=>b.onclick=()=>document.getElementById('grammar-'+b.dataset.index).classList.add('show'));shell.querySelector('#showEvidence')?.addEventListener('click',()=>document.getElementById('evidenceAnswer').classList.add('show'));shell.querySelector('#showCloze')?.addEventListener('click',()=>document.getElementById('clozeAnswer').classList.add('show'));shell.querySelector('#finishUnit').onclick=()=>finish(id,target)}

  function finish(id,target){const state=get();if(id==='test'){const fields=[...shell.querySelectorAll('[data-key]')];let ok=0;const details=[];fields.forEach((field,i)=>{const expected=field.dataset.key.toLowerCase().replace(/\s/g,'');const actual=field.value.toLowerCase().replace(/\s/g,'');const right=actual.length>0&&(actual.includes(expected)||expected.includes(actual));if(right)ok++;details.push((i+1)+'. '+(right?'正确':'待巩固')+'：参考答案 '+field.dataset.key)});const f=document.getElementById('testFeedback');f.className='feedback show '+(ok===fields.length?'good':'bad');f.innerHTML='<b>'+ok+' / '+fields.length+' 项正确</b><br>'+details.join('<br>')+'<br><br>待巩固项已标记为下一次学习优先处理。'}if(id==='test'&&!state.done.includes('test-'+target))state.done.push('test-'+target);else if(id!=='test'&&!state.done.includes(id))state.done.push(id);save(state);if(id==='test'){const button=document.getElementById('finishUnit');button.textContent='返回学习中心';button.onclick=hubView;return}hubView()}
  hubView();
})();
